layouts.spree.base_mailer.body:
{% assign brand = store.branding %}<mjml lang="{{ locale }}">
  <mj-head>
    <mj-title>{{ subject }}</mj-title>
    {% if brand.font_url %}<mj-font name="{{ brand.font_family | split: ',' | first }}" href="{{ brand.font_url }}" />{% endif %}
    <mj-attributes>
      <mj-all font-family="{{ brand.font_family }}" />
      <mj-section padding="0" />
      <mj-column padding="0" />
      <mj-text padding="0" color="{{ brand.text_color }}" font-size="14px" line-height="1.6" align="center" />
      <mj-button background-color="{{ brand.button_color }}" border="{{ brand.button_border }}" border-radius="8px" color="{{ brand.button_text_color }}" font-size="15px" font-weight="500" line-height="1.6" inner-padding="12px 20px" padding="32px 0 0" />
      <mj-table padding="0" color="{{ brand.text_color }}" font-size="14px" line-height="1.6" />
      <mj-class name="heading" font-family="{{ brand.heading_font_family }}" font-size="40px" font-weight="700" line-height="1.2" letter-spacing="-0.8px" color="{{ brand.heading_color }}" css-class="heading" />
      <mj-class name="greeting" padding="24px 0 0" font-size="15px" font-weight="500" color="{{ brand.heading_color }}" />
      <mj-class name="lead" padding="12px 0 0" />
      <mj-class name="note" padding="24px 0 0" font-size="13px" css-class="note" />
      <mj-class name="section-heading" padding="48px 0 16px" font-family="{{ brand.heading_font_family }}" font-size="16px" font-weight="500" letter-spacing="-0.16px" align="left" />
      <mj-class name="body" padding="16px 0 0" align="left" />
      <mj-class name="footer" padding="12px 0 0" font-size="11px" line-height="1.5" />
    </mj-attributes>
    <mj-style>
      {% if brand.font == 'inter' %}
      @font-face { font-family: "Geist"; font-style: normal; font-weight: 500 700; src: url("https://fonts.gstatic.com/s/geist/v4/gyByhwUxId8gMEwcGFU.woff2") format("woff2"); }
      @font-face { font-family: "Inter"; font-style: normal; font-weight: 400 450; src: url("https://fonts.gstatic.com/s/inter/v20/UcCO3FwrK3iLTeHuS_nVMrMxCp50SjIw2boKoduKmMEVuOKfMZg.ttf") format("truetype"); }
      @font-face { font-family: "Inter"; font-style: normal; font-weight: 500; src: url("https://fonts.gstatic.com/s/inter/v20/UcCO3FwrK3iLTeHuS_nVMrMxCp50SjIw2boKoduKmMEVuI6fMZg.ttf") format("truetype"); }
      @font-face { font-family: "Inter"; font-style: normal; font-weight: 600; src: url("https://fonts.gstatic.com/s/inter/v20/UcCO3FwrK3iLTeHuS_nVMrMxCp50SjIw2boKoduKmMEVuGKYMZg.ttf") format("truetype"); }
      {% endif %}
      a { color: {{ brand.link_color }}; }
      .hero > table { max-width: 420px; margin: 0 auto; }
      .note a { color: {{ brand.text_color }}; word-break: break-all; }
      .footer a { color: {{ brand.text_color }}; }
      .item { width: 100%; background-color: #F0F0F0; border-radius: 16px; margin: 0 0 8px; }
      .item_image { padding: 8px; width: 96px; }
      .item_thumb { display: block; width: 80px; height: auto; border-radius: 12px; }
      .item_thumb_placeholder { width: 80px; height: 80px; background-color: #E4E4E4; border-radius: 12px; }
      .item_info { padding: 8px 16px 8px 8px; }
      .item_name { font-size: 15px; line-height: 1.5; font-weight: 500; color: {{ brand.heading_color }}; text-decoration: none; }
      .item_meta { margin: 2px 0 0; font-size: 13px; line-height: 1.5; color: {{ brand.text_color }}; }
      .item_amount { padding: 8px 16px 8px 8px; text-align: right; white-space: nowrap; }
      .item_qty { margin: 0; font-size: 13px; line-height: 1.5; color: {{ brand.text_color }}; }
      .item_price { margin: 2px 0 0; font-size: 15px; line-height: 1.5; font-weight: 500; color: {{ brand.heading_color }}; }
      .summary td { padding: 6px 0; font-size: 14px; line-height: 1.6; color: {{ brand.text_color }}; }
      .summary_value { font-size: 15px; font-weight: 500; text-align: right; white-space: nowrap; color: {{ brand.heading_color }}; }
      .summary_sub { display: block; font-size: 13px; line-height: 1.5; }
      .summary_total td { padding: 14px 0 0; border-top: 1px solid #E8E9E9; font-weight: 500; color: {{ brand.heading_color }}; }
      .summary_total .summary_value { font-weight: 600; }
      .mailer_hero h1 { margin: 0; font-family: {{ brand.heading_font_family }}; font-size: 40px; line-height: 1.2; letter-spacing: -0.8px; font-weight: 700; color: {{ brand.heading_color }}; }
      .mailer_hero p { margin: 12px 0 0; }
      .mailer_hero .greeting { margin-top: 24px; font-size: 15px; font-weight: 500; color: {{ brand.heading_color }}; }
      .mailer_hero .sub { margin-top: 24px; font-size: 13px; }
      @media only screen and (max-width: 600px) {
        .heading div { font-size: 32px !important; letter-spacing: -0.64px !important; }
      }
    </mj-style>
  </mj-head>
  <mj-body background-color="{{ brand.background_color }}" width="640px">
    <mj-wrapper background-color="{{ brand.card_color }}" padding="56px 24px">
      <mj-section padding="0 0 32px">
        <mj-column>
          {% if store.logo_url and store.logo_width %}
            <mj-image src="{{ store.logo_url }}" href="{{ store.url }}" alt="{{ store.name }}" width="{{ store.logo_width }}px" height="32px" padding="0" />
          {% elsif store.logo_url %}
            <mj-text><a href="{{ store.url }}"><img src="{{ store.logo_url }}" alt="{{ store.name }}" height="32" style="height: 32px; width: auto; border: 0;" /></a></mj-text>
          {% else %}
            <mj-text font-size="22px" font-weight="700" color="{{ brand.heading_color }}" text-transform="uppercase"><a href="{{ store.url }}" style="color: {{ brand.heading_color }}; text-decoration: none;">{{ store.name }}</a></mj-text>
          {% endif %}
        </mj-column>
      </mj-section>
      {{ content_for_layout }}
    </mj-wrapper>
    <mj-section padding="64px 24px">
      <mj-column>
        <mj-text font-size="13px" line-height="1.5" css-class="footer"><a href="{{ store.url }}" style="font-weight: 500; text-decoration: none;">{{ store.name }}</a></mj-text>
        {% if store.address != blank %}<mj-text mj-class="footer">{{ store.address }}</mj-text>{% endif %}
        {% if store.support_email != blank %}<mj-text mj-class="footer" css-class="footer"><a href="mailto:{{ store.support_email }}">{{ store.support_email }}</a></mj-text>{% endif %}
        <mj-text mj-class="footer" padding="20px 0 0">&copy; {{ 'now' | date: '%Y' }} {{ store.name }}</mj-text>
      </mj-column>
    </mj-section>
  </mj-body>
</mjml>

